static void fill_weights(struct ggml_tensor*w,int kind,int pattern){size_t n=ggml_nbytes(w),bs=ggml_type_size(w->type);uint8_t*p=w->data;for(size_t i=0;i<n;++i)p[i]=pattern==1?0:pattern==2?255:(uint8_t)(next()>>24);for(size_t b=0;b<n/bs;++b){uint16_t d=pattern==1?0:b%2?0xb000:0x2c00;if(kind==12){for(int j=0;j<4;++j){uint16_t sc;memcpy(&sc,p+b*bs+48+2*j,2);sc=(sc&4095)|(((d>>(4*j))&15)<<12);memcpy(p+b*bs+48+2*j,&sc,2);}}else{memcpy(p+b*bs+dpos[kind],&d,2);if(dmpos[kind]>=0){uint16_t dm=pattern==1?0:0x2800;memcpy(p+b*bs+dmpos[kind],&dm,2);}}}}

